{"content":"import z3,pickle,time,json
from itertools import combinations
T,R,A=pickle.load(open('orbits.pkl','rb'));s=T-R;n=T*s;allmask=(1<<n)-1

def rot(a,j):
 h=(j*s)%n
 return ((a<<h)&allmask)|(a>>(n-h)) if h else a
O=[[rot(a,j) for j in range(T)] for a in A]
x=[z3.Bool('x%d'%i) for i in range(len(A))]
sol=z3.SolverFor('QF_FD');sol.set(timeout=300000)
conf=[[] for a in A]
for i,a in enumerate(A):
 for j in range(i):
  if any(not a&b for b in O[j]):
   sol.add(z3.Or(z3.Not(x[i]),z3.Not(x[j])))
   conf[i].append(j);conf[j].append(i)
for i in range(len(A)):
 sol.add(z3.Or([x[i]]+[x[j] for j in conf[i]]))
print('ready',len(A),flush=True)
start=time.time()
for it in range(10000):
 res=sol.check()
 if res!=z3.sat:
  print('result',res,'iterations',it,flush=True);break
 inds=[i for i in range(len(A)) if z3.is_true(sol.model()[x[i]])]
 edges=[a for i in inds for a in O[i]]
 c=[z3.Bool('c%d'%v) for v in range(n)]
 hit=z3.SolverFor('QF_FD');hit.set(timeout=30000)
 hit.add(z3.PbLe([(v,1) for v in c],T-1))
 for a in edges:hit.add(z3.Or([c[v] for v in range(n) if a>>v&1]))
 hr=hit.check()
 if hr==z3.unsat:
  print('FOUND',inds,flush=True)
  json.dump({'t':T,'r':R,'edges':edges},open('example8.json','w'));break
 if hr!=z3.sat:
  print('hitting',hr,flush=True);break
 C=sum(1<<v for v in range(n) if z3.is_true(hit.model()[c[v]]))
 sol.add(z3.Or([x[i] for i,orb in enumerate(O) if any(not a&C for a in orb)]))
 if it%100==0:print(it,'orbits',len(inds),'time',time.time()-start,flush=True)
"}

